local a={}a.REQUIRED_HOSTS=4;a.MIN_SEPARATION=1.0;a.COPLANAR_LIMIT=0.02;local function b(c,d)local e,f,g=c.x-d.x,c.y-d.y,c.z-d.z;return math.sqrt(e*e+f*f+g*g)end;local function h(i)local j={}for k,l in ipairs(i)do local m=false;for k,n in ipairs(j)do if b(l,n)<a.MIN_SEPARATION then m=true;break end end;if not m then j[#j+1]=l end end;return j end;local function o(p)local function q(c,d)return{x=c.x-d.x,y=c.y-d.y,z=c.z-d.z}end;local r,s,t=q(p[2],p[1]),q(p[3],p[1]),q(p[4],p[1])local u=math.abs(r.x*(s.y*t.z-s.z*t.y)-r.y*(s.x*t.z-s.z*t.x)+r.z*(s.x*t.y-s.y*t.x))/6;local v=0;for k,w in ipairs({r,s,t})do local x=math.sqrt(w.x*w.x+w.y*w.y+w.z*w.z)if x>v then v=x end end;if v==0 then return 0 end;return u/(v*v*v)end;a.DOP_GOOD=3.0;a.DOP_BAD=12.0;a.UERE=0.5;function a.pdop(y,z)if type(y)~="table"or#y<a.REQUIRED_HOSTS or type(z)~="table"then return nil end;local A={{0,0,0},{0,0,0},{0,0,0}}local B=0;for k,C in ipairs(y)do local e,f,g=z.x-C.x,z.y-C.y,z.z-C.z;local D=math.sqrt(e*e+f*f+g*g)if D>1e-6 then B=B+1;local E,F,G=e/D,f/D,g/D;A[1][1]=A[1][1]+E*E;A[1][2]=A[1][2]+E*F;A[1][3]=A[1][3]+E*G;A[2][1]=A[2][1]+F*E;A[2][2]=A[2][2]+F*F;A[2][3]=A[2][3]+F*G;A[3][1]=A[3][1]+G*E;A[3][2]=A[3][2]+G*F;A[3][3]=A[3][3]+G*G end end;if B<a.REQUIRED_HOSTS then return nil end;local c,d,H=A[1][1],A[1][2],A[1][3]local I,w,J=A[2][1],A[2][2],A[2][3]local K,p,L=A[3][1],A[3][2],A[3][3]local M=c*(w*L-J*p)-d*(I*L-J*K)+H*(I*p-w*K)if math.abs(M)<1e-12 then return nil end;local N=(w*L-J*p+c*L-H*K+c*w-d*I)/M;if N<=0 then return nil end;return math.sqrt(N)end;function a.dopQuality(O,P)P=P or a.UERE;if type(O)~="number"then return{quality=0,errorEst=nil,pdop=nil}end;local Q;if O<=a.DOP_GOOD then Q=1.0 elseif O>=a.DOP_BAD then Q=0.0 else Q=(a.DOP_BAD-O)/(a.DOP_BAD-a.DOP_GOOD)end;return{quality=Q,errorEst=O*P,pdop=O}end;function a.grade(i)local j=h(i or{})local R=#j;local S={}local T=true;if R<a.REQUIRED_HOSTS then T=false;S[#S+1]=("only %d usable host(s); need %d"):format(R,a.REQUIRED_HOSTS)elseif o(j)<a.COPLANAR_LIMIT then T=false;S[#S+1]="hosts are effectively coplanar -- the mirror cannot be resolved"end;return{usable=T,usableHosts=R,reasons=S}end;return a